scheduled_import_set.pre_script:
(function runPreImport() {
    var DS_NAME = 'CLM Sales data';

    // 1. Distinct customer codes from CLM Customer Masters
    var codes = [], seen = {};
    var ga = new GlideAggregate('x_birl3_clm_clm_customer_master1');
    ga.addQuery('is_active', true);              // confirm the real field name
    ga.addNotNullQuery('customer_code_sap');
    ga.groupBy('customer_code_sap');
    ga.query();
    while (ga.next()) {
        var c = ga.getValue('customer_code_sap').replace(/'/g, "''");
        if (!seen[c]) { seen[c] = true; codes.push("'" + c + "'"); }
    }

    // 2. Oracle IN-list limit is 1000, so chunk at 900
    var chunks = [];
    for (var i = 0; i < codes.length; i += 900) {
        chunks.push('customer IN (' + codes.slice(i, i + 900).join(',') + ')');
    }
    var customerFilter = chunks.length ? '(' + chunks.join(' OR ') + ')' : '1=0';

    var sql = "SELECT *\nFROM VW_MKT_CMNT_BPD_RMC_SALES\nWHERE " + customerFilter;

    // 3. Update the data source without touching connection_url
    var ds = new GlideRecord('sys_data_source');
    ds.addQuery('name', DS_NAME);
    ds.query();
    if (ds.next()) {
        var existingUrl = ds.getValue('connection_url');
        ds.setValue('sql_statement', sql);
        ds.setValue('connection_url', existingUrl); // keep it fixed
        ds.setWorkflow(false);                      // skip the rule that rebuilds the URL
        ds.update();
        gs.info('CLM Sales pre-import: wrote SQL with ' + codes.length + ' customer codes');
    } else {
        gs.error('CLM Sales pre-import: data source not found: ' + DS_NAME);
    }
})();
